// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2019, "2-3", [{"author":"Е. Бикмаев","question":"Люба рассказывает друзьям: «Я сегодня видела котёнка — вот такусенького!» Из этого описания понятно, что котёнок был … .","choices":["голодный","грустный","игривый","маленький","слабый."],"key":"Г","review":["Котёнок Любы","Прислушайся к слову «такусенького». Его уменьшительная форма похожа по смыслу на слова «малюсенький» и «крохотный».","Люба сообщает о размере котёнка. Он был очень маленький — вариант Г."]},{"author":"Е. Муравенко","question":"Во всех словах, кроме одного, прочерками заменены буквы <em>а</em>. В каком из слов один из прочерков заменяет букву <em>о</em>?","choices":["<em>б_р_б_н</em>","<em>к_р_нд_ш</em>","<em>р_скр_ск_</em>","<em>з_г_дк_</em>","<em>с_б_к_</em>."],"key":"Д","review":["Буквы под прочерками","Заполни прочерки так, чтобы получились знакомые слова. В словах «барабан», «карандаш», «раскраска» и «загадка» на всех этих местах стоят буквы а.","В слове «собака» первая пропущенная буква — о, а две следующие — а. Подходит вариант Д."]},{"author":"Л. Иткина","question":"В книжке «Кто как говорит» приводятся «слова» разных животных. Например, котёнок говорит «мяу-мяу». Какие два животных в этой книжке говорят одинаково?","choices":["телёнок и козлёнок","утёнок и лягушонок","жеребёнок и телёнок","цыплёнок и мышонок","котёнок и щенок."],"key":"Г","review":["Кто как говорит","Сравни звуки животных в каждой паре. Телёнок мычит, а козлёнок блеет. Утёнок крякает, лягушонок квакает, жеребёнок ржёт, котёнок мяукает, а щенок тявкает.","Тонкий писк цыплёнка и мышонка в детской книжке можно передать одинаково — «пи-пи». Это вариант Г."]},{"author":"И. Иткин","question":"Латинские буквы <strong>p</strong> и <strong>q</strong> обладают некоторой особенностью, которой, кроме них, обладает ещё только одна пара латинских букв. Какая?","choices":["<strong>a</strong> и <strong>z</strong>","<strong>b</strong> и <strong>d</strong>","<strong>c</strong> и <strong>g</strong>","<strong>i</strong> и <strong>y</strong>","<strong>r</strong> и <strong>s</strong>."],"key":"Б","review":["Пара латинских букв","В строчных p и q длинная черта уходит вниз. Круглая часть у p справа, а у q слева. Одну букву можно получить из другой отражением в вертикальном зеркале.","У b и d круглые части тоже расположены по противоположным сторонам, а длинные черты направлены вверх. Это зеркальная пара из варианта Б."]},{"author":"И. Рубанов","question":"Кто из этих животных не родня остальным?","choices":["<em>бык</em>","<em>жеребёнок</em>","<em>кобыла</em>","<em>конь</em>","<em>лошадь</em>."],"key":"А","review":["Животные и их родня","Жеребёнок — детёныш лошади, кобыла — взрослая самка, а конь — взрослый самец. Все эти названия относятся к лошадям.","Бык — взрослый самец крупного рогатого скота. Его детёныш — телёнок. Лишнее слово «бык» в варианте А."]},{"author":"И. Рубанов","question":"Джон Доу работает с кистями и красками. Иногда ему позируют. Несколько его работ висят на стенах музеев. Кто он по профессии?","choices":["маляр","художник","скульптор","фотограф","парикмахер."],"key":"Б","review":["Работа Джона Доу","Кисть и краски нужны и маляру, и художнику. Подсказку дают две другие детали — Джону позируют, а его работы выставляют на стенах музеев.","Позировать можно для портрета, написанного красками. Значит, Джон Доу — художник, вариант Б."]},{"author":"Е. Бикмаев","question":"В сказке Александра Милна про Винни-Пуха медвежонок так объедается в гостях у Кролика, что не может выбраться из его узкой норы. Догадайтесь, как назвал переводчик сказки Борис Заходер то положение, в которое попал Винни-Пух.","choices":["затруднительное","неразрешимое","пренеприятное","безвыходное","полуподвижное."],"key":"Г","review":["В гостях у Кролика","Винни-Пуху трудно выбраться из норы. Представь, что переводчик подбирает прилагательное, в котором слышится слово «выход».","«Безвыходное положение» обычно означает, что трудно найти решение. Здесь выражение шутливо совпадает с тем, что Пух буквально застрял в выходе. Это вариант Г."]},{"author":"Е. Бикмаев","question":"В какой паре слова соотносятся по смыслу не так, как в остальных?","choices":["<em>стакан — стаканчик</em>","<em>ящик — ящичек</em>","<em>кусок — кусочек</em>","<em>стол — столик</em>","<em>груз — грузчик</em>."],"key":"Д","review":["Что изменилось в слове","Стаканчик, ящичек, кусочек и столик — названия того же предмета, но меньшего размера или с ласковым оттенком.","Грузчик — человек, который переносит груз. У этого слова смысл связан с работой человека, поэтому выделяем пару «груз — грузчик» в варианте Д."]},{"author":"Б. Иомдин и М. Иомдин","question":"<em>Миша споткнулся и ... кожу на коленке</em>. Заполните пропуск.","choices":["<em>сдерел</em>","<em>сдёр</em>","<em>стёр</em>","<em>сдёрнул</em>","<em>содрал</em>."],"key":"Д","review":["Ссадина на коленке","По описанию Миша одним движением повредил кожу при падении. Для этого есть выражение «содрать кожу».","В прошедшем времени о мальчике говорят «содрал». «Стёр кожу» обычно говорит о повреждении от трения, например от тесной обуви. Для падения привычнее «споткнулся и содрал кожу на коленке», вариант Д."]},{"author":"Е. Бикмаев","question":"В мультфильме «38 попугаев» удав просит мартышку передать _______ слонёнку. Мартышка передаёт его, но слонёнок, не понимая, спрашивает: «А где же этот _______?» Какое слово мы дважды пропустили?","choices":["<em>секрет</em>","<em>привет</em>","<em>совет</em>","<em>ответ</em>","<em>вопрос</em>."],"key":"Б","review":["Просьба удава","Вспомни, что часто просят передать знакомому, которого сейчас нет рядом. Так удав может поздороваться со слонёнком через мартышку.","Обычно достаточно сказать «тебе привет». Слонёнок ищет его словно вещь, и в этом шутка. В оба пропуска подходит «привет», вариант Б."]},{"author":"Б. Иомдин","question":"Что бывает красным и чёрным, но обычно не бывает синим?","choices":["море","глаза","карандаш","перец","хлеб."],"key":"Г","review":["Красное и чёрное","У моря и глаз бывает синий цвет, а карандаш легко найти любого из трёх цветов. Хлеб обычно называют чёрным или белым.","Приправы называют «красный перец» и «чёрный перец». «Синий перец» не обычное название приправы. Подходит вариант Г."]},{"author":"Л. Фёдорова","question":"Для изготовления перины на Руси обычно использовали натуральный материал, полученный от … .","choices":["овец","коз","гусей","кошек","кроликов."],"key":"В","review":["Из чего делали перину","Перина — мягкая постель с набивкой. В её названии слышится слово «перо».","Перья и пух можно взять у птицы. Из перечисленных животных птица только гусь, поэтому выбираем «гусей» в варианте В."]},{"author":"Е. Бикмаев","question":"В сказке «Репка» друг за другом тянут репку дед, бабка, внучка, жучка, кошка, мышка. Что им нужно сделать, чтобы встать в алфавитном порядке?","choices":["дед и бабка должны поменяться местами","бабка и внучка должны поменяться местами","кошка и мышка должны поменяться местами","дед должен встать между внучкой и жучкой","дед должен встать между жучкой и кошкой."],"key":"Г","review":["Очередь у репки","Сравни первые буквы имён с алфавитом. Правильный порядок букв — б, в, д, ж, к, м.","Бабка и внучка уже стоят друг за другом, как и жучка, кошка и мышка. Переставь деда между внучкой и жучкой. Получится весь нужный порядок — вариант Г."]},{"author":"Е. Муравенко","question":"В одном рассказе Владимира Сутеева говорится о том, как вся семья отправилась в поездку и всем купили билеты, а котёнок ехал бесплатно. Папа сказал, что он „едет ______“. Ваня удивился: «Не понимаю, как может котёнок „ехать ______“»?\nКакое слово должно стоять на месте каждого пропуска?","choices":["<em>щенком</em>","<em>кошкой</em>","<em>волком</em>","<em>зайцем</em>","<em>лисой</em>."],"key":"Г","review":["Билет для котёнка","О пассажире, который едет без билета, говорят «едет зайцем». Для котёнка семейство отдельного билета не купило.","Папа употребляет «зайцем» в переносном смысле, а Ваня представляет зайца как животное. В обоих местах подходит вариант Г."]},{"author":"Е. Бикмаев","question":"В мультфильме «Высокая горка» на семью воробья Чика напал кот, но живущие рядом птицы вместе с Чиком прогоняют кота. Воробей хвастается воробьихе Чирике:\n— Ты видела, как ___...\n— Как ___? — удивлённо перебивает его воробьиха.\n— Как ___, Чирика, — исправляется воробей.\nЗаполните пропуски.","choices":["<em>мы</em>, <em>вы</em>, <em>я</em>","<em>вы</em>, <em>мы</em>, <em>я</em>","<em>мы</em>, <em>ты</em>, <em>я</em>","<em>я</em>, <em>ты</em>, <em>мы</em>","<em>я</em>, <em>вы</em>, <em>мы</em>."],"key":"Г","review":["Кто прогнал кота","Чик сначала хочет похвастаться, будто он один прогнал кота. Поэтому в его фразе звучит «я», а Чирика переспрашивает «ты?».","Тогда Чик вспоминает о помощи соседей и говорит от имени всех — «мы». Порядок «я, ты, мы» дан в варианте Г."]},{"author":"Е. Муравенко","question":"Во всех данных словах «спрятаны» названия частей лица, но только в одном слове — сразу два названия. В каком?","choices":["<em>юность</em>","<em>доброта</em>","<em>глобус</em>","<em>мухомор</em>","<em>свекольник</em>."],"key":"В","review":["Части лица внутри слов","Ищи названия частей лица в нескольких соседних буквах. В «юности» найдётся «нос», в «доброте» — «рот», в «мухоморе» — «ухо», а в «свекольнике» — «веко».","Раздели слово «глобус» на г, лоб и ус. В нём сразу два названия — «лоб» и «ус». Это вариант В."]},{"author":"Б. Иомдин","question":"Дети играли в настольную игру, выкладывая слова из фишек с буквами. Но некоторые слова ведущий не принимал, потому что они нарушали правила, например: МОСКВА, КИТАЙ, АНТОН. А какое ещё слово нарушило правило?","choices":["ГОРОД","СТРАНА","ИМЯ","НАЗВАНИЕ","СВЕТА."],"key":"Д","review":["Правило настольной игры","Москва — название города, Китай — название страны, Антон — имя человека. Все три слова являются именами собственными.","«Город», «страна», «имя» и «название» обозначают целые группы или понятия. Имя человека среди вариантов одно — Света. Оно нарушает правило игры, вариант Д."]},{"author":"Б. Иомдин","question":"В какой паре уменьшительное имя соотносится с полным не совсем так, как в остальных?","choices":["<em>Дмитрий — Дима</em>","<em>Тимофей — Тима</em>","<em>Роман — Рома</em>","<em>Зинаида — Зина</em>","<em>Любовь — Люба</em>."],"key":"А","review":["Полные и короткие имена","У Тимофея, Романа, Зинаиды и Любови короткие имена начинаются с тех же трёх букв — Тим, Ром, Зин и Люб. К ним прибавляется а.","В начале «Дмитрий» буквы м и и стоят в порядке «Дми», а в «Дима» — в порядке «Дим». Порядок букв изменился только в этой паре. Ответ А."]},{"author":"Е. Муравенко","question":"Если в слово <em>пуд</em> между буквами <em>п</em> и <em>у</em> добавить <em>р</em>, получится слово <em>пруд</em>. Подобным образом — вставляя букву <em>р</em> между какими-то двумя буквами — можно получить новое слово из каждого данного ниже слова. Но только из одного слова таким образом можно получить целых два новых слова. Из какого?","choices":["<em>пот</em>","<em>пакет</em>","<em>кот</em>","<em>зубы</em>","<em>сок.</em>"],"key":"В","review":["Вставка буквы р","Вставляй р только между буквами, сохраняя их порядок. Например, «пот» даёт «порт», «пакет» — «паркет», «зубы» — «зубры», «сок» — «срок».","В слове «кот» есть два удачных места. Между к и о получается «крот», а между о и т — «корт». Значит, выбираем вариант В."]},{"author":"С. Переверзева","question":"Заполните в правильном порядке пропуски в отрывке из рассказа Б. В. Шергина «Лебяжья река»:\n<em>Получится для мухи... домок-теремок. К ней постойщики приедут. Пойдёт</em> <em>житьё-бытьё. Муха-___, Блоха-___, Комар-___, Таракан-___</em>.","choices":["<em>Поскакуха</em>, <em>Горюха</em>, <em>Пискун</em>, <em>Шаркун</em>","<em>Горюха</em>, <em>Поскакуха</em>, <em>Шаркун</em>, <em>Пискун</em>","<em>Поскакуха</em>, <em>Горюха</em>, <em>Шаркун</em>, <em>Пискун</em>","<em>Горюха</em>, <em>Поскакуха</em>, <em>Пискун</em>, <em>Шаркун</em>","<em>Пискун</em>, <em>Шаркун</em>, <em>Горюха</em>, <em>Поскакуха</em>."],"key":"Г","review":["Постояльцы теремка","Блоха прыгает, поэтому она Поскакуха. Комар издаёт тонкий писк, поэтому он Пискун. Из прозвищ для мухи остаётся рифмующееся «Горюха».","Таракану достаётся имя Шаркун от глагола «шаркать». В порядке героев получаем «Горюха, Поскакуха, Пискун, Шаркун» — вариант Г."]},{"author":"И. Рубанов","question":"У композитора было шестеро детей: Дора, Ляля, Мирандолина, Регина, Сольвейг, Фаина. Сейчас родилась ещё одна дочь. Как он собирается её назвать?","choices":["Аида","Джульетта","Иоланта","Кармен","Сильва."],"key":"Д","review":["Имена детей композитора","Прочитай начала имён. У Доры, Ляли, Мирандолины, Регины, Сольвейг и Фаины они совпадают с названиями нот до, ля, ми, ре, соль и фа.","В музыкальном ряду осталась нота си. С неё начинается только имя Сильва. Это вариант Д."]},{"author":"Б. Иомдин и Ю. Халеева","question":"Взлетев на воздушном шарике к дуплу с пчёлами, Винни-Пух озабоченно сказал Кристоферу Робину:\n<em>— По-моему, пчёлы что-то подозревают!</em>\n<em>— Что именно?</em>\n<em>— Не знаю я. Но только, по-моему, они ведут себя подозрительно!</em>\nОчевидно, Винни-Пух не знает, что <em>подозревать</em> и <em>вести себя подозрительно</em> — это не одно и то же. А какие две фразы означают одно и то же?","choices":["<em>Пчёлы что-то замечают</em> и <em>Пчёлы ведут себя замечательно</em>","<em>Пчёлы что-то полагают</em> и <em>Пчёлы ведут себя положительно</em>","<em>Пчёлы возмущаются</em> и <em>Пчёлы ведут себя возмутительно</em>","<em>Пчёлы поражаются</em> и <em>Пчёлы ведут себя поразительно</em>","<em>Пчёлы стесняются</em> и <em>Пчёлы ведут себя стеснительно</em>."],"key":"Д","review":["Что делают пчёлы","Сравни поступок пчёл и впечатление, которое он производит. Если пчёлы возмущаются, они сами испытывают недовольство. А их возмутительное поведение вызывает недовольство наблюдателя.","«Ведут себя стеснительно» описывает их собственное стеснение. Здесь обе фразы передают одно и то же, поэтому подходит вариант Д."]},{"author":"Л. Фёдорова","question":"Буратино не знает, как правильно пишутся гласные в его имени. Сколько у него способов записать своё имя, чтобы оно сохранило своё звучание?","choices":["только один","два","три","четыре","пять."],"key":"Г","review":["Как записать имя","Произнеси «Бурати́но». У в первом слоге и ударная и слышны ясно. А перед ударным слогом и о в конце без ударения звучат так, что их можно принять за другую из этих двух букв.","На каждом из двух мест выбираем а или о. Получаются Буратино, Буратина, Буротино и Буротина. Всего 2 × 2 = 4 записи, вариант Г."]},{"author":"И. Иткин","question":"Антон написал книжечку «Язык инопланетян».\nБоря написал книжицу «Как одеваются феи».\nВолодя написал книгу «Африканские драконы».\nГриша написал книжищу «Зачем единорогу рог».\nДима написал книжку «Невероятные истории».\nУ кого из них, скорее всего, получился самый толстый том?","choices":["у Антона","у Бори","у Володи","у Гриши","у Димы."],"key":"Г","review":["Книги пяти друзей","Слова «книжечка», «книжица» и «книжка» обозначают книгу с уменьшительным или ласковым оттенком. «Книга» звучит нейтрально.","Слово «книжища» с суффиксом -ищ- подчёркивает большой размер. Так назван том Гриши, поэтому вероятнее всего он самый толстый. Ответ Г."]},{"author":"Б. Иомдин","question":"Догадайтесь, что это за надписи с пропусками, и выберите лишнюю.","choices":["<em>шля___льто</em>","<em>пижа___йка</em>","<em>пид__ет</em>","<em>бри___нсы</em>","<em>брю___но.</em>"],"key":"Д","review":["Надписи с пропусками","Восстанови по два слова с общей частью. В шля[па]льто спрятались шляпа и пальто, в пижа[ма]йка — пижама и майка, в пид[жак]ет — пиджак и жакет, в бри[джи]нсы — бриджи и джинсы.","В брю[ки]но соединяются «брюки» и «кино». Кино выделяется среди всех исходных слов, потому что остальные называют одежду или головные уборы. Подходит вариант Д."]},{"author":"И. Рубанов","question":"Петя гулял три часа. За первый час он прошёл ... километра, за второй — ... километра, за третий — ... километра. Сколько всего километров прошёл Петя, если известно, что многоточия тут заменяют три разных числа, название каждого из которых записывается одним словом?","choices":["семь","восемь","девять","десять","одиннадцать."],"key":"В","review":["Три часа ходьбы","Проверь, после каких целых чисел говорят «километра». Подходят «два», «три» и «четыре». «Двадцать два» тоже годилось бы по форме, но это уже два слова.","Из трёх разных целых чисел получаем 2 + 3 + 4 = 9. Ещё говорят «полтора километра». С двумя целыми числами «полтора» даст дробную сумму, а в списке все ответы целые. Подходит «девять», вариант В."]},{"author":"О. Кузнецова","question":"В старину на Руси был обряд под названием «влазины». В честь какого события его совершали?","choices":["новоселья","выздоровления","начала охоты","годовщины свадьбы","окончания сбора урожая."],"key":"А","review":["Обряд с необычным именем","В слове «влазины» угадывается глагол «влазить», то есть входить внутрь. Среди событий в задаче есть одно, связанное со входом в новое жилище.","Влазинами называли обряд заселения в дом. Его совершали в честь новоселья, вариант А."]},{"author":"Е. Бикмаев","question":"В мультфильме «Лягушка-путешественница» по сказке В. М. Гаршина утка, расхваливая юг, говорит: «Юг — это ____, напоминающий ____». Второе пропущенное слово можно получить из первого, вычеркнув в нём первую букву. Какая это буква?","choices":["<em>к</em>","<em>о</em>","<em>с</em>","<em>в</em>","<em>у</em>."],"key":"А","review":["Рассказ утки о юге","Утка хвалит юг. Подбери короткое слово для прекрасного места — «рай».","Добавь в начале к. Получится «край», и вся фраза звучит естественно — «Юг — это край, напоминающий рай». Нужная буква к, вариант А."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
